import 'package:flutter/material.dart';import '../services/auth_service.dart';import '../models/models.dart';
class UsersScreen extends StatelessWidget{UsersScreen({super.key});final a=AuthService();@override Widget build(BuildContext c)=>StreamBuilder<List<AppUser>>(stream:a.users(),builder:(c,s){final us=s.data??[];return Column(children:[Padding(padding:const EdgeInsets.all(12),child:FilledButton.icon(onPressed:(){final n=TextEditingController(),name=TextEditingController();showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('إضافة مندوب'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'اسم المستخدم')),TextField(controller:name,decoration:const InputDecoration(labelText:'الاسم'))]),actions:[FilledButton(onPressed:()async{await a.createRepRecord(n.text,name.text);if(c.mounted)Navigator.pop(c);},child:const Text('حفظ'))]));},icon:const Icon(Icons.person_add),label:const Text('إضافة مندوب'))),Expanded(child:ListView(children:us.map((u)=>ListTile(leading:CircleAvatar(child:Text(u.name.isEmpty?'؟':u.name[0])),title:Text(u.name),subtitle:Text('${u.username} • ${u.role==UserRole.admin?'مسؤول':'مندوب'}'),trailing:u.role==UserRole.admin?null:Switch(value:u.active,onChanged:(v)=>a.setUserActive(u,v))).toList()))]);});}
}
